import React,{useMemo,useRef,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {EchoLivingLightPreviewSurface} from '../../src/components/EchoLivingLightPreview.jsx';
import {createLivingLightRegistry} from '../../src/living-light/registry.js';
import {createEchoLivingLightCue} from '../../src/domain/echo-living-light-editor.js';
import {livingLightPreparedBinding} from '../../src/domain/living-light-prepared-binding.js';
import {fixture} from './living-light-signals.mjs';
const input=fixture(0),binding=livingLightPreparedBinding(input),registry=createLivingLightRegistry(),thing=registry.entries.find(t=>t.variantKind==='continuous-profile'),resolveRegistry=async()=>registry;
const journey={schemaVersion:'hapa.living-light.journey.v1',journeyId:'fixture:bound-journey',revisionId:'fixture:bound-r1',parentRevisionId:null,title:'Exact prepared master recovery',songId:input.songId,sourceBindingRef:{bindingId:binding.bindingId,revisionId:binding.revisionId},state:'draft-unresolved',mode:'continuous',seed:109,instances:[{instanceId:'fixture:use',thingRef:{thingId:thing.thingId,revisionId:thing.revisionId},parameters:{},bindings:{}}],schedule:[{instanceId:'fixture:use',startUs:0,endUs:2e6}],actorTreatment:'none',mediaSlots:[]};
const project={song_id:input.songId,duration:2,living_light_cues:[createEchoLivingLightCue({journey,cueId:'fixture:cue',startUs:0,journeyWindow:{startUs:0,endUs:2e6}})]};
const ordinary={sourcePolicy:'ordinary-visualizers'};
function Proof(){const clock=useRef(.5),[time,setTime]=useState(.5),[mode,setMode]=useState('ready'),[active,setActive]=useState(true),[reads,setReads]=useState(0),[frame,setFrame]=useState(null);
 const client=useMemo(()=>({request:async route=>{if(route.startsWith('/journeys/'))return {journey};if(route.startsWith('/performance?')){setReads(n=>n+1);if(mode==='missing')throw Object.assign(Error('This exact master has no prepared performance bundle.'),{code:'echo_performance_not_prepared'});const performance=structuredClone(input.performance);if(mode==='changed')performance.fingerprint='sha256:'+'e'.repeat(64);return {songId:input.songId,sourcePolicy:'living-light-assets-v1',performance,sourceValidation:{analysisExecuted:false,masterAudioHash:input.playbackReceipt.sourceHash}};}throw Error('Unexpected route: '+route);}}),[mode]);
 return <main style={{maxWidth:900,margin:'auto',fontFamily:'sans-serif'}}><h1>Exact prepared Journey recovery</h1><p>Synthetic source receipts and curves; real native renderer and production Director surface. No audio processing or album writes.</p><div>{['ready','changed','missing'].map(value=><button key={value} onClick={()=>setMode(value)}>Source {value}</button>)}<button onClick={()=>{clock.current=1.5;setTime(1.5);}}>Seek 1.5s</button><button onClick={()=>setActive(!active)}>{active?'Leave preview':'Return to preview'}</button></div><p>Owner reads: {reads}</p><p>Song time: {time}s · painted signal time: {frame?.songUs??'none'}</p><div style={{position:'relative',aspectRatio:'16/9'}}><EchoLivingLightPreviewSurface project={project} clockRef={clock} currentTime={time} active={active} audioReceipt={input.playbackReceipt} preparedPerformance={ordinary} registryResolver={resolveRegistry} client={client} onFrame={setFrame}/></div></main>;
}
const root=createRoot(document.getElementById('root'));root.render(<Proof/>);if(import.meta.hot)import.meta.hot.dispose(()=>root.unmount());
